@app.route("/api/events", methods=["POST"])
def create_event():
    data = request.get_json() or {}
    title = (data.get("title") or "").strip()
    starts = data.get("starts")
    capacity = int(data.get("capacity", 0))
    if not title or not starts or capacity < 1:
        return jsonify(error="title, start time and capacity are required"), 400
    cur = mysql.connection.cursor()
    cur.execute("SELECT COUNT(*) FROM events WHERE organiser_id = %s AND starts = %s", (session["user_id"], starts))
    if cur.fetchone()[0]:
        return jsonify(error="you already have an event at that time"), 409
    cur.execute("INSERT INTO events (organiser_id, title, starts, capacity) VALUES (%s, %s, %s, %s)", (session["user_id"], title, starts, capacity))
    mysql.connection.commit()
    return jsonify(id=cur.lastrowid), 201

def _alter_field(self, model, old_field, new_field, old_type, new_type,
                     old_db_params, new_db_params, strict=False):
        super(DatabaseSchemaEditor, self)._alter_field(
            model, old_field, new_field, old_type, new_type, old_db_params,
            new_db_params, strict,
        )
        # Added an index? Create any PostgreSQL-specific indexes.
        if not old_field.db_index and not old_field.unique and (new_field.db_index or new_field.unique):
            like_index_statement = self._create_like_index_sql(model, new_field)
            if like_index_statement is not None:
                self.execute(like_index_statement)

        # Removed an index? Drop any PostgreSQL-specific indexes.
        if (old_field.db_index or old_field.unique) and not (new_field.db_index or new_field.unique):
            index_to_remove = self._create_index_name(model, [old_field.column], suffix='_like')
            index_names = self._constraint_names(model, [old_field.column], index=True)
            for index_name in index_names:
                if index_name == index_to_remove:
                    self.execute(self._delete_constraint_sql(self.sql_delete_index, model, index_name))

