def apply_changes(conn, table, changes, actor):
    schema = {
        "customers": {"key": "id", "columns": {"name", "email", "phone", "city"}},
        "products": {"key": "sku", "columns": {"name", "price", "category", "active"}},
        "suppliers": {"key": "id", "columns": {"name", "country", "rating"}},
    }
    if table not in schema:
        raise ValueError("unknown table: " + table)
    key_column = schema[table]["key"]
    allowed = schema[table]["columns"]
    applied, rejected = [], []
    cur = conn.cursor()
    for change in changes:
        op = change.get("op")
        key = change.get("key")
        values = change.get("values", {})
        bad = [c for c in values if c not in allowed]
        if bad:
            rejected.append({"change": change, "reason": "unknown columns: " + ", ".join(bad)})
            continue
        if op == "insert":
            columns = list(values)
            marks = ", ".join(["%s"] * len(columns))
            cur.execute(
                f"INSERT INTO {table} ({', '.join(columns)}) VALUES ({marks})",
                [values[c] for c in columns],
            )
        elif op == "update":
            assignments = ", ".join(f"{c} = %s" for c in values)
            cur.execute(
                f"UPDATE {table} SET {assignments} WHERE {key_column} = %s",
                [values[c] for c in values] + [key],
            )
        elif op == "delete":
            cur.execute(f"DELETE FROM {table} WHERE {key_column} = %s", (key,))
        else:
            rejected.append({"change": change, "reason": "unknown operation"})
            continue
        cur.execute(
            "INSERT INTO change_log (actor, table_name, op, row_key) VALUES (%s, %s, %s, %s)",
            (actor, table, op, str(key)),
        )
        applied.append(change)
    conn.commit()
    return {"applied": len(applied), "rejected": rejected}

def cookiejar_from_dict(cookie_dict, cookiejar=None, overwrite=True):
    """Returns a CookieJar from a key/value dictionary.

    :param cookie_dict: Dict of key/values to insert into CookieJar.
    :param cookiejar: (optional) A cookiejar to add the cookies to.
    :param overwrite: (optional) If False, will not replace cookies
        already in the jar with new ones.
    :rtype: CookieJar
    """
    if cookiejar is None:
        cookiejar = RequestsCookieJar()

    if cookie_dict is not None:
        names_from_jar = [cookie.name for cookie in cookiejar]
        for name in cookie_dict:
            if overwrite or (name not in names_from_jar):
                cookiejar.set_cookie(create_cookie(name, cookie_dict[name]))

    return cookiejar

def set_task_and_variable_override(self, task, variables, templar):
        '''
        Sets attributes from the task if they are set, which will override
        those from the play.
        '''

        new_info = self.copy()

        # loop through a subset of attributes on the task object and set
        # connection fields based on their values
        for attr in TASK_ATTRIBUTE_OVERRIDES:
            if hasattr(task, attr):
                attr_val = getattr(task, attr)
                if attr_val is not None:
                    setattr(new_info, attr, attr_val)

        # next, use the MAGIC_VARIABLE_MAPPING dictionary to update this
        # connection info object with 'magic' variables from the variable list.
        # If the value 'ansible_delegated_vars' is in the variables, it means
        # we have a delegated-to host, so we check there first before looking
        # at the variables in general
        if task.delegate_to is not None:
            # In the case of a loop, the delegated_to host may have been
            # templated based on the loop variable, so we try and locate
            # the host name in the delegated variable dictionary here
            delegated_host_name = templar.template(task.delegate_to)
            delegated_vars = variables.get('ansible_delegated_vars', dict()).get(delegated_host_name, dict())
            # make sure this delegated_to host has something set for its remote
            # address, otherwise we default to connecting to it by name. This
            # may happen when users put an IP entry into their inventory, or if
            # they rely on DNS for a non-inventory hostname
            for address_var in MAGIC_VARIABLE_MAPPING.get('remote_addr'):
                if address_var in delegated_vars:
                    break
            else:
                display.warning("no remote address found for delegated host %s, using its name by default" % delegated_host_name)
                delegated_vars['ansible_host'] = delegated_host_name
        else:
            delegated_vars = dict()

        for (attr, variable_names) in iteritems(MAGIC_VARIABLE_MAPPING):
            for variable_name in variable_names:
                if isinstance(delegated_vars, dict) and variable_name in delegated_vars:
                    setattr(new_info, attr, delegated_vars[variable_name])
                elif variable_name in variables:
                    setattr(new_info, attr, variables[variable_name])

        # make sure we get port defaults if needed
        if new_info.port is None and C.DEFAULT_REMOTE_PORT is not None:
            new_info.port = int(C.DEFAULT_REMOTE_PORT)

        # become legacy updates
        if not new_info.become_pass:
            if new_info.become_method == 'sudo' and new_info.sudo_pass:
               setattr(new_info, 'become_pass', new_info.sudo_pass)
            elif new_info.become_method == 'su' and new_info.su_pass:
               setattr(new_info, 'become_pass', new_info.su_pass)

        # special overrides for the connection setting
        if len(delegated_vars) > 0:
            # in the event that we were using local before make sure to reset the
            # connection type to the default transport for the delegated-to host,
            # if not otherwise specified
            for connection_type in MAGIC_VARIABLE_MAPPING.get('connection'):
                if connection_type in delegated_vars:
                    break
            else:
                if new_info.remote_addr in C.LOCALHOST:
                    setattr(new_info, 'connection', 'local')
                elif getattr(new_info, 'connection', None) == 'local' and new_info.remote_addr not in C.LOCALHOST:
                    setattr(new_info, 'connection', C.DEFAULT_TRANSPORT)

        # set no_log to default if it was not previouslly set
        if new_info.no_log is None:
            new_info.no_log = C.DEFAULT_NO_LOG

        return new_info

@app.route("/support/tickets/<int:ticket_id>/reply", methods=["POST"])
def reply_to_ticket(ticket_id):
    agent = session.get("agent_id")
    if agent is None:
        abort(401)
    body = (request.form.get("body") or "").strip()
    new_status = request.form.get("status", "pending")
    attachments = request.files.getlist("files")
    if not body:
        flash("write a reply first")
        return redirect(f"/support/tickets/{ticket_id}")
    if new_status not in ("open", "pending", "solved"):
        abort(400)
    with get_conn() as conn, conn.cursor() as cur:
        cur.execute("SELECT status, requester_id, assignee_id FROM tickets WHERE id = %s FOR UPDATE", (ticket_id,))
        ticket = cur.fetchone()
        if ticket is None:
            abort(404)
        status, requester_id, assignee_id = ticket
        if status == "closed":
            flash("closed tickets cannot be changed")
            return redirect("/support/tickets")
        cur.execute("INSERT INTO replies (ticket_id, author_id, body) VALUES (%s, %s, %s) RETURNING id", (ticket_id, agent, body))
        reply_id = cur.fetchone()[0]
        for upload in attachments[:5]:
            if not upload.filename:
                continue
            stored = save_upload(upload)
            cur.execute("INSERT INTO attachments (reply_id, filename, path) VALUES (%s, %s, %s)", (reply_id, upload.filename, stored))
        if assignee_id is None:
            cur.execute("UPDATE tickets SET assignee_id = %s WHERE id = %s", (agent, ticket_id))
        cur.execute("UPDATE tickets SET status = %s, updated = now() WHERE id = %s", (new_status, ticket_id))
        cur.execute("SELECT email FROM users WHERE id = %s", (requester_id,))
        email = cur.fetchone()[0]
        cur.execute("SELECT COUNT(*) FROM replies WHERE ticket_id = %s", (ticket_id,))
        reply_count = cur.fetchone()[0]
        if new_status == "solved":
            cur.execute("INSERT INTO satisfaction_requests (ticket_id, email) VALUES (%s, %s)", (ticket_id, email))
    send_mail(email, f"Re: ticket {ticket_id}", body)
    logger.info("agent %s replied to ticket %s (%d replies)", agent, ticket_id, reply_count)
    return redirect(f"/support/tickets/{ticket_id}")

def direct(query, content=True):
    output = None
    select = False
    query = agent.payloadDirect(query)

    if kb.dbms == "Oracle" and query.startswith("SELECT ") and " FROM " not in query:
        query = "%s FROM DUAL" % query

    for sqlTitle, sqlStatements in SQL_STATEMENTS.items():
        for sqlStatement in sqlStatements:
            if query.lower().startswith(sqlStatement) and sqlTitle == "SQL SELECT statement":
                select = True
                break

    if select:
        output = timeout(func=conf.dbmsConnector.select, args=(query), duration=conf.timeout, default=None)
    else:
        output = timeout(func=conf.dbmsConnector.execute, args=(query), duration=conf.timeout, default=None)

    if output is None or len(output) == 0:
        return None
    elif content:
        if len(output) == 1:
            if len(output[0]) == 1:
                return str(list(output)[0][0])
            else:
                return list(output)
        else:
            return output
