        if start >= end:
            raise ValueError("slot must end after it starts")
        conn.execute("INSERT INTO show_slots (show_id, weekday, start_time, end_time) VALUES (?, ?, ?, ?)", (show_id, weekday, start, end))
    conn.execute("INSERT INTO schedule_changes (show_id, editor, changed_at) VALUES (?, ?, datetime('now'))", (show_id, editor))
    conn.commit()
    log.info("schedule of %s replaced by %s", show[0], editor)
    return len(slots)

