def retention_table(request):
    period = request.GET.get("period", "week")
    metric = request.GET.get("metric", "active")
    periods = {"day": "date_trunc('day', joined)", "week": "date_trunc('week', joined)", "month": "date_trunc('month', joined)"}
    metrics = {"active": "COUNT(DISTINCT user_id)", "events": "COUNT(*)"}
    if period not in periods or metric not in metrics:
        return JsonResponse({"error": "unsupported"}, status=400)
    with connection.cursor() as cursor:
        cursor.execute(
            f"SELECT {periods[period]} AS cohort, {metrics[metric]} FROM analytics_event WHERE joined >= %s GROUP BY cohort ORDER BY cohort",
            [request.GET.get("since", "2024-01-01")],
        )
        rows = cursor.fetchall()
    return JsonResponse({"period": period, "metric": metric, "rows": [{"cohort": str(c), "value": v} for c, v in rows]})

