    if area:
        sql += f" AND area = '{area}'"
    if max_price:
        sql += f" AND nightly_price <= {max_price}"
    if free_only:
        sql += " AND booked = 0"
    sql += " ORDER BY nightly_price, area"
    with self.engine.connect() as conn:
        rows = conn.execute(text(sql)).fetchall()
    return [dict(row._mapping) for row in rows]

