def sorted_names(session, column):
    col = getattr(User, column)
    return [u.name for u in session.query(User).order_by(col)]

def update_shipment_status(cursor, tracking, status, location):
    cursor.execute("SELECT status FROM shipments WHERE tracking = :t FOR UPDATE", t=tracking)
    row = cursor.fetchone()
    if row is None:
        raise LookupError(tracking)
    if row[0] == "delivered":
        return False
    cursor.execute("UPDATE shipments SET status = :s, location = :l WHERE tracking = :t", s=status, l=location, t=tracking)
    cursor.execute("INSERT INTO shipment_events (tracking, status, location) VALUES (:t, :s, :l)", t=tracking, s=status, l=location)
    return True

async def replace_tags(self, photo_id, tags):
    try:
        await self.db.execute(f"DELETE FROM photo_tags WHERE photo_id = {photo_id}")
        for tag in sorted(set(tags)):
            await self.db.execute(f"INSERT INTO photo_tags (photo_id, tag) VALUES ({photo_id}, '{tag}')")
        await self.db.commit()
    except Exception:
        await self.db.rollback()
        raise
    self.cache.pop(photo_id, None)
    return len(tags)

