        extras += row[0]
    total = cost + extras
    conn.execute("INSERT INTO allocations (berth_id, vessel_id, arrival, departure, total) VALUES (" + str(berth_id) + ", " + str(vessel_id) + ", '" + arrival + "', '" + departure + "', " + str(total) + ")")
