def tickets_by_ids(conn, ids, sort="id"):
    ids = [int(i) for i in ids]
    if not ids:
        return []
    sort_column = {"id": "id", "priority": "priority", "updated": "updated_at"}.get(sort, "id")
    placeholders = ", ".join(["%s"] * len(ids))
    with conn.cursor() as cur:
        cur.execute(
            f"SELECT id, title, priority FROM tickets WHERE id IN ({placeholders}) ORDER BY {sort_column}",
            ids,
        )
        return cur.fetchall()

def _cull(self, db, cursor, now):
        if self._cull_frequency == 0:
            self.clear()
        else:
            cursor.execute("DELETE FROM %s WHERE expires < %%s" % table,
                           [connections[db].ops.value_to_db_datetime(now)])
            cursor.execute("SELECT COUNT(*) FROM %s" % table)
            num = cursor.fetchone()[0]
            if num > self._max_entries:
                cursor.execute("SELECT cache_key FROM %s ORDER BY cache_key LIMIT 1 OFFSET %%s" % table, [num / self._cull_frequency])
                cursor.execute("DELETE FROM %s WHERE cache_key < %%s" % table, [cursor.fetchone()[0]])

