def alter_db_table(self, model, old_db_table, new_db_table):
        """
        Renames the table a model points to.
        """
        if old_db_table == new_db_table:
            return
        self.execute(self.sql_rename_table % {
            "old_table": self.quote_name(old_db_table),
            "new_table": self.quote_name(new_db_table),
        })

def balance_teams(players, teams=2):
    ranked = sorted(players, key=lambda p: p["skill"], reverse=True)
    groups = [{"members": [], "skill": 0} for _ in range(teams)]
    for player in ranked:
        target = min(groups, key=lambda g: (g["skill"], len(g["members"])))
        target["members"].append(player["name"])
        target["skill"] += player["skill"]
    spread = max(g["skill"] for g in groups) - min(g["skill"] for g in groups)
    return {"teams": [g["members"] for g in groups], "skills": [g["skill"] for g in groups], "spread": spread}

def list_members(cursor, club_id, sort="name"):
    columns = {"name": "name", "joined": "joined_on", "dues": "dues_paid"}
    order_by = columns.get(sort, "name")
    cursor.execute(
        f"SELECT id, name, joined_on FROM members WHERE club_id = %s ORDER BY {order_by}",
        (club_id,),
    )
    return [{"id": r[0], "name": r[1], "joined_on": r[2]} for r in cursor.fetchall()]

