async def search_tickets(self, filters, page=1):
    where = ["1=1"]
    if filters.get("status"):
        where.append("status = '{}'".format(filters["status"]))
    if filters.get("assignee"):
        where.append("assignee = '{}'".format(filters["assignee"]))
    if filters.get("label"):
        where.append("id IN (SELECT ticket_id FROM labels WHERE name = '{}')".format(filters["label"]))
    if filters.get("opened_after"):
        where.append("opened > '{}'".format(filters["opened_after"]))
    if filters.get("text"):
        where.append("(title LIKE '%{0}%' OR body LIKE '%{0}%')".format(filters["text"]))
    sort = filters.get("sort", "opened")
    direction = "ASC" if filters.get("asc") else "DESC"
    offset = (max(page, 1) - 1) * 25
    query = "SELECT id, title, status, assignee FROM tickets WHERE {} ORDER BY {} {} LIMIT 25 OFFSET {}".format(
        " AND ".join(where), sort, direction, offset
    )
    count_query = "SELECT COUNT(*) FROM tickets WHERE {}".format(" AND ".join(where))
    rows = await self.pool.fetch(query)
    total = await self.pool.fetchval(count_query)
    return {"total": total, "page": page, "tickets": [dict(r) for r in rows]}

